import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"kiwa v2.1 x-thread (English)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v2.1/x-thread-en.md","filePath":"announcements/v2.1/x-thread-en.md"}'),n={name:"announcements/v2.1/x-thread-en.md"};function s(o,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="kiwa-v2-1-x-thread-english" tabindex="-1">kiwa v2.1 x-thread (English) <a class="header-anchor" href="#kiwa-v2-1-x-thread-english" aria-label="Permalink to &quot;kiwa v2.1 x-thread (English)&quot;">​</a></h1><h2 id="tweet-1" tabindex="-1">Tweet 1 <a class="header-anchor" href="#tweet-1" aria-label="Permalink to &quot;Tweet 1&quot;">​</a></h2><p>kiwa v2.1 is out — quality-metrics deepening IV. <strong>@kiwa-lab/quality-metrics v2.1</strong> adds adaptive drift threshold learning: <code>learnAdaptiveThreshold</code> learns per-axis threshold from history using mean + k*stdev (default k=2 = 95% CI), <code>pickThresholdForAxis</code> returns per-axis or aggregate fallback. First <strong>4 PR rhythm milestone after v2.0 rename</strong>, <strong>systematic pattern 44th application (statistical inference variant)</strong>, <strong>47 milestone streak</strong> achieved.</p><h2 id="tweet-2" tabindex="-1">Tweet 2 <a class="header-anchor" href="#tweet-2" aria-label="Permalink to &quot;Tweet 2&quot;">​</a></h2><p>Statistical inference SSOT: mean + k*stdev with axis-independent learning captures per-axis volatility (perf variance high → wider threshold, coverage variance low → narrower). baseline=0 Infinity samples excluded, minSampleCount=3 filter default. shape contract preserving absolute (existing v0.5-v0.6 API unchanged).</p><h2 id="tweet-3" tabindex="-1">Tweet 3 <a class="header-anchor" href="#tweet-3" aria-label="Permalink to &quot;Tweet 3&quot;">​</a></h2><p>dogfood-quality-metrics-adaptive-threshold-app new, 4-pattern workflow (collectRolling + learnFromHistory + evaluateWithLearnedThreshold + explainLearnedGate), 10 tests pass. depth-5 operation-continuation pattern 3rd case compound deepening.</p><h2 id="tweet-4" tabindex="-1">Tweet 4 <a class="header-anchor" href="#tweet-4" aria-label="Permalink to &quot;Tweet 4&quot;">​</a></h2><p><code>pnpm add -D @kiwa-lab/quality-metrics@^2.1</code>. Migration: <a href="https://cardene777.github.io/kiwa/migrations/v2.0-to-v2.1" target="_blank" rel="noreferrer">https://cardene777.github.io/kiwa/migrations/v2.0-to-v2.1</a></p><p>Backward compat absolute: 既存 API 変更 0, opt-in for v2.1 consumers. Existing 193 tests continue passing.</p><p>4 subs completed (v2.1-1 v2.1 threshold-learning + 13 tests / v2.1-2 dogfood 10 tests / v2.1-3 docs 47 streak / v2.1-4 publish).</p><p>#kiwa #quality-metrics #statistical-inference #adaptive-threshold #testing #vitest</p>',12)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
